        n = len(sub)
        if n % 2 != 0:
            return False
        half = n // 2
        return sub[:half] == sub[half:]

    max_length = 0

    # Check all possible tandem repeats in the original string s
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            sub = s[i:j]
            if is_tandem_repeat(sub):
                max_length = max(max_length, j - i)

