import sys

def max_tandem_repeat_length(s, k):
    def is_tandem_repeat(t):
        n = len(t)
        for i in range(n // 2):
            if t[i] != t[i + n // 2]:
                return False
        return True

    max_length = 0
    for i in range(len(s) + 1):
        for j in range(k + 1):
            candidate = s[:i] + s[-j:] * 2
            if is_tandem_repeat(candidate):
                max_length = max(max_length, len(candidate))

    return max_length

